import { useNavigate } from 'react-router-dom';

import { Training } from 'pages/trainingHub/domain';

import {
  StyledAllTrainingsCard,
  StyledAllTrainingsCardImages,
  StyledCtaLink,
  StyledTrainingImage,
  TrainingCounter,
} from './AllTrainingsCard.styles';

export const AllTrainingsCard = ({
  trainings,
  pillarId,
}: {
  trainings: Training[];
  pillarId?: string;
}) => {
  const navigate = useNavigate();

  const ITEMS_TO_SHOW = 4;
  const trainingsToShow = trainings.slice(0, ITEMS_TO_SHOW);
  const remainingTrainings = trainings.length - ITEMS_TO_SHOW;
  const trainingCount = remainingTrainings > 0 ? `${remainingTrainings}+` : '';

  const handleNavigateToAllTrainings = (pillarId: string) => {
    if (pillarId) {
      navigate(`/training-hub/${pillarId}`);
    } else {
      navigate('/training-hub/recently-added');
    }
  };

  return (
    <StyledAllTrainingsCard
      onClick={() => handleNavigateToAllTrainings(pillarId)}
    >
      <StyledAllTrainingsCardImages>
        {trainingsToShow.map((training) => (
          <StyledTrainingImage
            key={training.id}
            src={training.image}
            alt="Training"
          />
        ))}
        <TrainingCounter>{trainingCount}</TrainingCounter>
      </StyledAllTrainingsCardImages>
      <StyledCtaLink>Show All</StyledCtaLink>
    </StyledAllTrainingsCard>
  );
};
